(() => {
  function navigate(hash) {
    history.pushState({ route: hash.replace(/^#/, '') }, '', hash);
    window.dispatchEvent(new PopStateEvent('popstate', { state: history.state }));
  }

  const HOME_SELECTOR = '.home-bar, .s6-files-home, .s8f-files-home, .s9f-home';

  function removeWfHome(root = document) {
    // wf-home is a duplicate indicator generated by fidelity shells.
    // It must never be retained or renamed: physically remove the node.
    root.querySelectorAll('.wf-home').forEach((indicator) => indicator.remove());
  }

  function removeDuplicateHomeIndicators(root = document) {
    removeWfHome(root);

    root.querySelectorAll('.screen').forEach((screen) => {
      const indicators = Array.from(screen.querySelectorAll(HOME_SELECTOR));
      if (indicators.length <= 1) return;

      const keep = screen.querySelector('.s6-files-home, .s8f-files-home') ||
        screen.querySelector(':scope > .home-bar') ||
        screen.querySelector('.home-bar') ||
        screen.querySelector('.s9f-home') ||
        indicators[0];

      indicators.forEach((indicator) => {
        if (indicator !== keep) indicator.remove();
      });
    });

    root.querySelectorAll('.phone, .s1-device, .s3-device, .s5-device, .s6-device, .s6o-device, .s9f-root').forEach((shell) => {
      const indicators = Array.from(shell.querySelectorAll(HOME_SELECTOR));
      if (indicators.length <= 1) return;
      const keep = shell.querySelector('.s6-files-home, .s8f-files-home') || shell.querySelector('.home-bar') || indicators[0];
      indicators.forEach((indicator) => {
        if (indicator !== keep) indicator.remove();
      });
    });
  }

  document.addEventListener('click', (event) => {
    const target = event.target.closest('button, [data-goto], [data-s5-action], [data-s6-action]');
    if (!target) return;

    if (
      target.matches('[data-s5-action="agree"]') ||
      target.matches('#s05-consent-screen > [data-goto="date-entry"]')
    ) {
      event.preventDefault();
      event.stopImmediatePropagation();
      navigate('#policy-selection');
      return;
    }

    if (
      target.matches('[data-s6-action="policy-confirm"]') ||
      target.matches('#selection-screen #confirm-button')
    ) {
      event.preventDefault();
      event.stopImmediatePropagation();
      navigate('#date-entry');
      return;
    }
  }, true);

  function start() {
    removeDuplicateHomeIndicators();

    const observer = new MutationObserver(() => removeDuplicateHomeIndicators());
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['hidden']
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, { once: true });
  } else {
    start();
  }
})();
